for n in (1, 2, 3, 4, 5):
    base = "cursos/Lessn-M%d" % n
    d = json.load(open(base + "/video/escenas_def.json", encoding="utf-8"))
    sp = importlib.util.spec_from_file_location("bl%d" % n, base + "/voz/bloques.py"); m = importlib.util.module_from_spec(sp); sp.loader.exec_module(m)
    txt = dict(m.BLOQUES)
    out = ["# Lessn · Módulo %d · %s\n" % (n, d["titulo"]),
           "Proyecto: `%s/video`. Narración: `%s/voz/ritmo/narracion_v2.wav` (voz oficial). **La sincronía sale siempre de `AC.cue`/`AC.cueEnd`/`AC.blockStart`, nunca de segundos escritos a mano.** Marca: **Lessn** (la voz dice «Leson»; en pantalla se escribe siempre «Lessn»). Interfaz real medida: `%s/agentes/ref_ui/%s` y `cursos/UI_LESSN_COMUN.md` (+ capturas en esa carpeta y `cursos/Lessn-assets/`). Crudo original: `%s/crudo/`. El guion fue reescrito para describir la app de hoy (que cambió mucho respecto al crudo).\n" % (base, base, base, n, base)]
    out.append("## Escenas\n")
    for e in d["escenas"]:
        tipo, idea = I[n][e["id"]]
        out.append("### %s · %s  (tipo: %s)\nArchivo: `compositions/%s-%s.html`, composition-id `%s-%s`. Bloques de voz: %s. Fondo del maestro (tu escena es transparente sobre él): centro %s, medio %s, borde %s, textura %s.\n\n**Narración (limpia):**\n" % (e["id"], e["nombre"], tipo, e["id"], e["nombre"], e["id"], e["nombre"], ", ".join(e["bloques"]), *e["tema"]))
        for b in e["bloques"]:
            lim = re.sub(r"\[[^\]]*\]\s*", "", txt[b]).replace("{Lessn}", "Lessn"); lim = re.sub(r"\*([^*]+)\*", r"\1", lim)
            out.append("- `%s`: %s\n" % (b, lim))
        out.append("\n**Concepto:** %s\n" % idea)
    open("cursos/MODULO_LESSN_%d.md" % n, "w", encoding="utf-8").write("\n".join(out))
print("ok")
